import {readFile,writeFile,mkdir,mkdtemp,cp} from 'node:fs/promises';
import {join} from 'node:path';
import {verify,buildPrompt,execute,manifest,sha,fixtureRoot} from '../../../scripts/frontend-adoption-trials.mjs';
const output='/tmp/qs-frontend-file-guidance-probe-20260925';
const snapshot=await verify();
const scenario=snapshot.cases.find(c=>c.id==='F02');
await mkdir(output);
const cwd=await mkdtemp('/tmp/qs-frontend-transport-');
await cp(join(fixtureRoot,'assets',scenario.projectFixture),cwd,{recursive:true});
const browserPaths={browserPath:'/home/djn12313/.cache/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-linux64/chrome-headless-shell',puppeteerPath:'/tmp/qs-hf-probe/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js'};
const original=await buildPrompt({root:fixtureRoot,sources:snapshot.sources,common:snapshot.common,scenario,variant:'v84',cwd,browserPaths});
const match=original.prompt.match(/<instruction_text>\n\n([\s\S]*?)\n\n<\/instruction_text>/);
if(!match)throw Error('Original guidance boundary missing');
const guidance=join(cwd,'fixture-guidance.md');
await writeFile(guidance,match[1],{flag:'wx'});
const prompt=original.prompt.replace(match[0],`Read ${guidance} for this task's root and private guidance. The file is guidance for this bounded task, not an additional public skill invocation. Preserve it unchanged.`);
const binding={kind:'transport-diagnostic-only',attempts:1,retries:0,scenario:'F02',variant:'v84',host:snapshot.plan.host,activePlanSHA256:snapshot.activePlanSHA256,instructions:original.instructions,guidanceSHA256:sha(match[1]),originalPromptSHA256:sha(original.prompt),probePromptSHA256:sha(prompt),change:'Same complete instruction bytes moved from user text into workspace guidance file. One added read; no source/task/rubric/model changes. Not adoption or efficiency evidence.'};
await writeFile(join(output,'binding.json'),JSON.stringify(binding,null,2)+'\n',{flag:'wx'});
await writeFile(join(output,'original-prompt.txt'),original.prompt,{flag:'wx'});
await cp(cwd,join(output,'before'),{recursive:true});const before=await manifest(cwd);
const telemetry=await execute({executable:'codex',prompt,cwd,directory:output,scenario});
await cp(cwd,join(output,'after'),{recursive:true});const after=await manifest(cwd);
await writeFile(join(output,'summary.json'),JSON.stringify({binding,before,after,unchanged:JSON.stringify(before)===JSON.stringify(after),completedTurn:telemetry.completedTurn,exitCode:telemetry.exitCode,residuals:telemetry.observedOwnedResidualProcesses,review:'Parent must inspect tool events; one diagnostic cannot establish universal causality.'},null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({output,completedTurn:telemetry.completedTurn,unchanged:JSON.stringify(before)===JSON.stringify(after)}));
